test "t0" {
    assert (
        transform_data(
            [
                {'name': 'Tom', 'score': 60},
                {'name': 'Jerry', 'score': 70},
                {'name': 'Tom', 'score': 80},
                {'name': 'Jerry', 'score': 90}
            ]
        )
        == (['Tom', 'Jerry', 'Tom', 'Jerry'], [60, 70, 80, 90])
    );;
}

